        run: [at(0.6, { do: 'break', node: 'cache' }), at(1.2, co('cache', 'mất dữ liệu đệm', 'bad', { dy: 1.8 })), load('rds', 1, 2.2), at(2.6, co('rds', 'quá tải!', 'bad', { dy: 1.8 }))],
        loop: { start: 1.4, every: 0.35, run: [pk('app', 'rds', { size: 0.6, speed: 11, color: REQ })] },
